<?php
declare(strict_types=1);
require __DIR__.'/../bootstrap.php';
use Ismile\App;use Ismile\Auth;use Ismile\Db;use Ismile\ApprovedWorkshops;use Ismile\Workshops;use Ismile\WorkshopCatalog;use Ismile\WorkshopTickets;use Ismile\UserError;use Ismile\Payments\Payments;
if(App::isLive()||!str_starts_with((string)App::config('db.name'),'ismile_workshop_test_real_')||App::config('payments.psoola.api_base')!=='http://127.0.0.1:8830')throw new RuntimeException('Use an isolated workshop database and the local provider fixture.');
$passed=0;$check=static function(string $name,bool $ok)use(&$passed):void{if(!$ok)throw new RuntimeException('FAILED: '.$name);$passed++;echo "PASS: $name\n";};
$reject=static function(callable $fn):bool{try{$fn();return false;}catch(UserError){return true;}};
$fixture=static fn(string $query=''):array=>json_decode((string)file_get_contents('http://127.0.0.1:8830/fixture'.$query),true);
$basePosts=$fixture()['posts'];
foreach(['simplified-direct-veneers','mastering-zirconia-veneers','crown-vs-veneer'] as $id)$fixture('/stock?id='.$id.'&available=25');
$owner=Db::one('SELECT * FROM admin_users WHERE id=?',[Auth::createUser('workshops-owner@example.invalid','Workshop Owner','owner',bin2hex(random_bytes(16)))]);
Db::run('DELETE FROM workshops');
foreach([['soft-tissue-implants','Dr. Sarah Hassan'],['composite-restorations','Dr. Alan Karim']] as [$id,$speaker])Db::insert('workshops',['id'=>$id,'title_en'=>'Demo','speaker_en'=>$speaker,'total_seats'=>30,'price'=>100,'currency'=>'USD','created_at'=>App::now(),'updated_at'=>App::now()]);
$publication=ApprovedWorkshops::publish($owner);
$check('only the three approved workshops replace unbooked demos',count(Workshops::all())===3&&count($publication['deleted_demos'])===2);
$check('publication is idempotent',ApprovedWorkshops::publish($owner)===['already_published'=>true]);
$catalog=WorkshopCatalog::all();$crown=WorkshopCatalog::one('crown-vs-veneer');
$check('Crown vs Veneer is on 19 November in Iraq time',$crown['scheduledDate']==='2026-11-19'&&$crown['startTime']==='13:00'&&$crown['endTime']==='17:00');
$check('provider prices and availability are verified',count(array_filter($catalog,static fn($w)=>$w['availabilityVerified']&&$w['seatsLeft']===25))===3&&$crown['price']===120000);
$company=WorkshopCatalog::one('mastering-zirconia-veneers');$check('Vanest retains both company phones',$company['organizer']==='company'&&$company['companyPhones']===['0771 366 6464','0751 420 3598']);
$seed=static function(string $status,string $suffix):array{$id=Db::insert('registrations',['ref'=>'WR'.strtoupper(bin2hex(random_bytes(5))),'first_name'=>'Workshop','father_name'=>'Test','grandfather_name'=>'Attendee','email'=>'workshop-'.$suffix.'@example.invalid','phone'=>'+9647501234567','city'=>'Sulaimani','specialty'=>'gp','ticket_type'=>'professional','status'=>$status,'comp_reason'=>$status==='complimentary'?'Fixture':null,'view_nonce'=>bin2hex(random_bytes(16)),'created_at'=>App::now(),'updated_at'=>App::now(),'paid_at'=>App::now()]);return Db::one('SELECT * FROM registrations WHERE id=?',[$id]);};
$paid=$seed('paid','paid');$cancelled=$seed('cancelled','cancelled');$free=$seed('complimentary','free');
$check('unregistered email cannot request a workshop',$reject(fn()=>Workshops::registerOnline('simplified-direct-veneers','unknown@example.invalid')));
foreach([$cancelled,$free] as $person)$check('a '.$person['status'].' summit registration is not a paid prerequisite',$reject(fn()=>Workshops::registerOnline('simplified-direct-veneers',$person['email'])));
$check('Vanest cannot be booked through the email endpoint',$reject(fn()=>Workshops::registerOnline('mastering-zirconia-veneers',$paid['email'])));
Workshops::registerOnline('simplified-direct-veneers',$paid['email']);$booking=Db::one('SELECT * FROM workshop_bookings WHERE registration_id=?',[$paid['id']]);
$check('email registration creates an unpaid request and no PSOOLA sale',$booking['payment_status']==='unpaid'&&$fixture()['posts']===$basePosts);
$check('duplicate workshop requests are refused',$reject(fn()=>Workshops::registerOnline('simplified-direct-veneers',$paid['email'])));
$check('unpaid workshop requests cannot issue paid tickets',$reject(fn()=>WorkshopTickets::issue((int)$booking['id'],$owner))&&$fixture()['posts']===$basePosts);
Db::update('workshop_bookings',['payment_status'=>'paid','amount_paid'=>100000,'paid_how'=>'cash','paid_at'=>App::now(),'paid_recorded_by'=>$owner['id']],'id=?',[$booking['id']]);
WorkshopTickets::issue((int)$booking['id'],$owner);$state=$fixture();$order=Db::one('SELECT * FROM workshop_ticket_orders WHERE booking_id=?',[$booking['id']]);
$check('collected payment issues the matching workshop ticket exactly once',$state['posts']===($basePosts+1)&&$order['provider_status']==='paid'&&$state['orders'][count($state['orders'])-1]['request']['eventId']==='m579695hxrck33njrcfxxv05zd8hfrs4'&&$state['orders'][count($state['orders'])-1]['request']['items'][0]['quantity']===1&&!isset($state['orders'][count($state['orders'])-1]['request']['returnUrl']));
WorkshopTickets::issue((int)$booking['id'],$owner);$check('retry verifies the saved order without another sale',$fixture()['posts']===($basePosts+1));
$check('published remaining seats come from PSOOLA after sale',WorkshopCatalog::one('simplified-direct-veneers',true)['seatsLeft']===24);
$webhook=static function(string $id,string $event='order.paid')use($order):array{$body=json_encode(['id'=>$id,'type'=>$event,'data'=>['sessionId'=>$order['provider_session_id'],'partnerReference'=>$order['partner_reference']]]);$time=time();return Payments::handleWebhook('psoola',['X-Psoola-Signature'=>'t='.$time.',v1='.hash_hmac('sha256',$time.'.'.$body,'workshop-fixture-webhook')],$body);};
$payments=(int)Db::value('SELECT COUNT(*) FROM payments');$check('workshop webhook is routed independently of summit payments',$webhook('workshop-webhook-1')['status']===200&&(int)Db::value('SELECT COUNT(*) FROM payments')===$payments);
$reads=$fixture()['statusReads'];$webhook('workshop-webhook-1');$check('duplicate webhook delivery is idempotent',$fixture()['statusReads']===$reads);
$check('invalid workshop webhook signatures are refused',Payments::handleWebhook('psoola',['X-Psoola-Signature'=>'bad'],'{}')['status']===401);
$fixture('/refund?id='.rawurlencode($order['provider_session_id']));$webhook('workshop-webhook-2','order.refunded');$check('verified provider refunds are reflected on the workshop order',Db::value('SELECT provider_status FROM workshop_ticket_orders WHERE id=?',[$order['id']])==='refunded');
Db::update('registrations',['status'=>'cancelled'],'id=?',[$paid['id']]);$check('a cancelled summit registration cannot buy another workshop ticket',$reject(fn()=>WorkshopTickets::issue((int)$booking['id'],$owner))&&$fixture()['posts']===($basePosts+1));
echo $passed." real workshop integration checks passed.\n";
